{"filename":"script.js","content":"(function(){
  const api={
    base:'/api',
    async request(path,options={}){
      const resp=await fetch(this.base+path,{headers:{'Content-Type':'application/json'},...options});
      const data=await resp.json().catch(()=>null);
      if(!resp.ok){
        const err=new Error(data && data.error ? data.error : resp.statusText);
        err.status=resp.status; err.body=data; throw err;
      }
      return data;
    },
    getTasks(){return this.request('/tasks');},
    getTask(id){return this.request(`/tasks/${id}`);},
    createTask(payload){return this.request('/tasks',{method:'POST',body:JSON.stringify(payload)});},
    updateTask(id,payload){return this.request(`/tasks/${id}`,{method:'PUT',body:JSON.stringify(payload)});},
    deleteTask(id){return this.request(`/tasks/${id}`,{method:'DELETE'});},
    getUsers(){return this.request('/users');},
    getUser(id){return this.request(`/users/${id}`);},
    createUser(payload){return this.request('/users',{method:'POST',body:JSON.stringify(payload)});},
    updateUser(id,payload){return this.request(`/users/${id}`,{method:'PUT',body:JSON.stringify(payload)});},
    deleteUser(id){return this.request(`/users/${id}`,{method:'DELETE'});}
  };

  const ForgeAI=window.ForgeAI={pages:{},registerPage(slug,renderer){this.pages[slug]=renderer;}};

  function parseHash(){
    let hash=location.hash.slice(1)||'/';
    const [path,queryString]=hash.split('?');
    const search=new URLSearchParams(queryString||'');
    return {slug:path,search};
  }

  async function render(){
    const {slug,search}=parseHash();
    const root=document.getElementById('app');
    const page=ForgeAI.pages[slug];
    if(page){
      try{await page({root,profile:null,api,search});}
      catch(e){root.innerHTML='<p class="error">Error: '+(e.message||'Unexpected')+'</p>';}
    }else{root.innerHTML='<h2>Page not found</h2>';}
  }

  window.addEventListener('hashchange',render);
  window.addEventListener('load',()=>{render();});

  // Default home page
  ForgeAI.registerPage('/',async ({root})=>{root.innerHTML='<h2>Welcome to Task Tracker</h2><p>Select a section from the navigation.</p>';});
})();"}
